function getPerDisplayName(ticker) {
    return perTickerNameMap[ticker] || ticker;
}

function updatePerTags() {
    const container = document.getElementById('ticker-tags');
    if (!container) return;
    // index.html의 Global Filter 영역과 동기화
    if (typeof updateTags === 'function') updateTags();
}

async function loadPerData() {
    const seq = ++perLoadSeq;
    if (perRequestController) perRequestController.abort();
    perRequestController = new AbortController();

    const container = document.getElementById('per-table-container');
    if (perTickers.length === 0) {
        perData = [];
        if (container) container.innerHTML = '<div class="per-empty">종목을 선택하면 밸류에이션 비교 결과가 표시됩니다</div>';
        return;
    }

    const loading = document.getElementById('per-loading');
    if (loading) loading.classList.remove('hidden');

    try {
        const res = await fetch(`/api/valuation?tickers=${encodeURIComponent(perTickers.join(','))}`, {
            cache: 'no-store',
            signal: perRequestController.signal,
        });
        if (!res.ok) throw new Error(`밸류에이션 API 오류 (${res.status})`);
        const data = await res.json();
        if (seq !== perLoadSeq) return;

        perData = Array.isArray(data.stocks) ? data.stocks : [];
        perData.forEach(s => {
            if (s.name && !perTickerNameMap[s.ticker]) perTickerNameMap[s.ticker] = s.name;
        });
        renderPerTable();

        const badge = document.getElementById('update-badge');
        if (badge) {
            const failed = Array.isArray(data.errors) ? data.errors.length : 0;
            badge.textContent = failed ? `${failed}개 종목 일부 데이터 누락` : '업데이트 완료';
            badge.classList.remove('hidden');
        }
    } catch (e) {
        if (e && e.name === 'AbortError') return;
        console.error('Valuation data error:', e);
        if (seq === perLoadSeq && container) {
            container.innerHTML = '<div class="per-empty">밸류에이션 데이터를 불러오지 못했습니다. 잠시 후 다시 시도해주세요.</div>';
        }
    } finally {
        if (seq === perLoadSeq && loading) loading.classList.add('hidden');
    }
}

function formatValue(val, format, isKR) {
    if (val === null || val === undefined || isNaN(val)) return '-';
    if (format === 'currency') return isKR ? `₩${Math.round(val).toLocaleString()}` : `$${val.toLocaleString()}`;
    if (format === 'percent') return `${val.toFixed(2)}%`;
    if (format === 'marketcap') {
        if (isKR) return `${(val / 100000000).toFixed(0)}억`;
        return `$${(val / 1000000000).toFixed(1)}B`;
    }
    return val.toLocaleString('ko-KR', { minimumFractionDigits: 1, maximumFractionDigits: 2 });
}

function renderPerTable() {
    const container = document.getElementById('per-table-container');
    const titleEl = document.getElementById('metric-title');
    const descEl = document.getElementById('metric-description');

    if (!container) return;

    const config = METRIC_CONFIG[currentMetric] || METRIC_CONFIG['overview'];

    if (titleEl) titleEl.textContent = config.title;
    if (descEl) descEl.textContent = config.description;

    if (perData.length === 0) {
        container.innerHTML = '<div class="per-empty">데이터를 불러오는 중...</div>';
        return;
    }

    // 1. 정렬 로직 적용
    let sortedData = [...perData];
    const sortField = config.sortKey;

    if ((currentSort === 'metric-asc' || currentSort === 'metric-desc') && sortField) {
        const direction = currentSort === 'metric-asc' ? 1 : -1;
        sortedData.sort((a, b) => {
            const av = Number(a[sortField]);
            const bv = Number(b[sortField]);
            const aValid = Number.isFinite(av) && a[sortField] !== null;
            const bValid = Number.isFinite(bv) && b[sortField] !== null;
            if (!aValid && !bValid) return 0;
            if (!aValid) return 1;
            if (!bValid) return -1;
            return (av - bv) * direction;
        });
    }

    let html = `<table class="per-table"><thead><tr><th>종목</th><th>현재가</th>`;
    config.columns.forEach(col => { html += `<th>${col.label}</th>`; });
    html += `</tr></thead><tbody>`;

    sortedData.forEach(stock => {
        const isKR = stock.ticker.includes('.KS') || stock.ticker.includes('.KQ');
        const hasPrice = stock.price != null && Number(stock.price) > 0;
        const priceStr = !hasPrice ? '-' : (isKR ? `₩${Math.round(Number(stock.price)).toLocaleString()}` : `$${Number(stock.price).toLocaleString('ko-KR', { maximumFractionDigits: 2 })}`);
        html += `<tr>
            <td class="stock-info-cell">
                <div class="stock-name">${perTickerNameMap[stock.ticker] || stock.name || stock.ticker}</div>
                <div class="stock-ticker">${stock.ticker}</div>
            </td>
            <td class="price-cell">${priceStr}</td>`;

        config.columns.forEach(col => {
            const val = stock[col.key];
            const color = col.color ? config.colorFunc(val) : 'inherit';
            html += `<td style="color:${color}; font-weight: ${col.color ? '600' : 'normal'}">${formatValue(val, col.format, isKR)}</td>`;
        });
        html += `</tr>`;
    });
    html += '</tbody></table>';

    // 바 차트 (시각 비교)
    const barKey = config.barKey;
    if (barKey && sortedData.length > 0) {
        const validData = sortedData.filter(s => s[barKey] != null && !isNaN(s[barKey]) && s[barKey] !== 0);
        if (validData.length > 0) {
            const vals = validData.map(s => Math.abs(s[barKey]));
            const maxVal = Math.max(...vals, 0.1);

            html += `<div class="per-bars">
                <div class="per-bars-title">${config.barLabel || config.title} 한눈에 보기</div>`;

            validData.forEach(stock => {
                const val = stock[barKey];
                const width = Math.min((Math.abs(val) / maxVal) * 100, 100);
                const color = config.colorFunc ? config.colorFunc(val) : '#3182F6';
                const label = getPerDisplayName(stock.ticker);

                html += `
                    <div class="per-bar-row">
                        <span class="per-bar-label">${label}</span>
                        <div class="per-bar-track">
                            <div class="per-bar-fill" style="width:${width}%; background:${color}"></div>
                        </div>
                        <span class="per-bar-value" style="color:${color}">${(val || 0).toFixed(1)}</span>
                    </div>`;
            });
            html += '</div>';
        }
    }

    container.innerHTML = html;
}

// Global Filter 상호작용 지점
window.addPerTickerDirect = function (ticker) {
    if (!perTickers.includes(ticker)) {
        perTickers.push(ticker);
        const activeTab = document.querySelector('.tab-btn.active')?.dataset.tab;
        if (activeTab === 'fwdper') loadPerData();
    }
};

window.removePerTicker = function (ticker) {
    perTickers = perTickers.filter(t => t !== ticker);
    perData = perData.filter(d => d.ticker !== ticker);
    // removeTicker() in chart.js is the single owner of global removal.
    // Calling it again here caused chart -> valuation -> chart recursion.
    const activeTab = document.querySelector('.tab-btn.active')?.dataset.tab;
    if (activeTab === 'fwdper') renderPerTable();
};

document.addEventListener('DOMContentLoaded', () => {
    // 탭 전환 로직 (통신 필요 시 loadPerData 호출)
    window.switchTab = function (tabId) {
        console.log('Switching to tab:', tabId);

        // 버튼 활성화 상태 변경
        document.querySelectorAll('.tab-btn').forEach(btn => {
            btn.classList.toggle('active', btn.dataset.tab === tabId);
        });

        // 콘텐츠 표시/숨김
        document.querySelectorAll('.tab-content').forEach(content => {
            if (content.id === `${tabId}-tab`) {
                content.classList.add('active');
                content.style.display = 'block';
            } else {
                content.classList.remove('active');
                content.style.display = 'none';
            }
        });

        // 글로벌 필터(상단 바) 노출 여부 조절
        const globalFilter = document.getElementById('global-filter');
        if (globalFilter) {
            globalFilter.style.display = (tabId === 'chart' || tabId === 'fwdper' || tabId === 'ideas') ? 'block' : 'none';
        }

        // 탭 전용 데이터 로드
        if (tabId === 'fwdper') {
            loadPerData();
        } else if (tabId === 'macro' && typeof loadMacroData === 'function') {
            loadMacroData();
        }
    };

    // 하단 탭 버튼들 이벤트 연결 (누락되었던 부분)
    document.querySelectorAll('.tab-btn').forEach(btn => {
        btn.addEventListener('click', () => switchTab(btn.dataset.tab));
    });

    // 지표 칩 클릭 이벤트
    document.querySelectorAll('.metric-chip').forEach(btn => {
        btn.addEventListener('click', () => {
            document.querySelectorAll('.metric-chip').forEach(b => b.classList.remove('active'));
            btn.classList.add('active');
            currentMetric = btn.dataset.metric;
            renderPerTable();
        });
    });

    // 정렬 버튼 이벤트
    document.querySelectorAll('.sort-btn').forEach(btn => {
        btn.addEventListener('click', () => {
            document.querySelectorAll('.sort-btn').forEach(b => b.classList.remove('active'));
            btn.classList.add('active');
            currentSort = btn.dataset.sort;
            renderPerTable();
        });
    });

    // 밸류에이션 탭을 열 때만 데이터 로드
});
;

/* --- static/js/valuation_bands.js --- */
// Historical PER/PBR valuation bands. Loaded after fwdper.js.
(() => {
  'use strict';

  let bandMetric = 'per';
  let bandTicker = null;
  let bandPayload = null;
  let bandChart = null;
  let resizeObserver = null;
  let requestController = null;
  let requestSeq = 0;

  const css = `
    .band-section{display:none;margin:16px 20px 24px;background:#fff;border:1px solid #eaedf0;border-radius:18px;padding:20px;box-shadow:0 2px 12px rgba(0,0,0,.035)}
    .band-head{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;margin-bottom:14px}
    .band-title{font-size:20px;font-weight:800;color:#191f28;margin:0 0 5px}.band-desc{font-size:13px;color:#6b7684;line-height:1.5;margin:0}
    .band-stock-tabs,.band-metric-tabs{display:flex;gap:7px;overflow-x:auto;scrollbar-width:none;-webkit-overflow-scrolling:touch}.band-stock-tabs::-webkit-scrollbar,.band-metric-tabs::-webkit-scrollbar{display:none}
    .band-stock-tabs{margin:14px 0 10px}.band-stock-btn,.band-metric-btn{border:1px solid #e5e8eb;background:#fff;color:#4e5968;border-radius:999px;padding:9px 12px;font-size:13px;font-weight:700;white-space:nowrap;cursor:pointer}
    .band-stock-btn.active,.band-metric-btn.active{background:#191f28;color:#fff;border-color:#191f28}.band-metric-tabs{margin:0 0 14px}.band-metric-btn{min-width:92px}
    .band-cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px;margin:0 0 14px}.band-card{background:#f7f8fa;border-radius:13px;padding:12px}.band-card span{display:block;color:#8b95a1;font-size:11px;margin-bottom:5px}.band-card strong{display:block;color:#191f28;font-size:17px;line-height:1.2}.band-card small{display:block;color:#6b7684;font-size:10px;margin-top:4px;line-height:1.3}
    .band-chart-wrap{position:relative;border:1px solid #edf0f2;border-radius:14px;overflow:hidden;background:#fff}.band-chart{height:340px;width:100%}.band-loading{height:340px;display:flex;align-items:center;justify-content:center;color:#8b95a1;font-size:13px}.band-foot{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;color:#8b95a1;font-size:11px;line-height:1.45;margin-top:10px}.band-legend{display:flex;gap:10px;flex-wrap:wrap}.band-dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:4px}.band-note{margin-top:10px;padding:10px 12px;border-radius:12px;background:#f7f8fa;color:#4e5968;font-size:12px;line-height:1.5}.band-empty{padding:34px 14px;text-align:center;color:#8b95a1;font-size:13px}
    @media(max-width:720px){.band-section{margin:10px 8px 18px;padding:14px;border-radius:16px}.band-head{display:block}.band-title{font-size:18px}.band-cards{grid-template-columns:repeat(2,minmax(0,1fr));gap:7px}.band-card{padding:10px}.band-card strong{font-size:16px}.band-chart{height:300px}.band-loading{height:300px}.band-stock-btn,.band-metric-btn{min-height:40px;padding:9px 13px}.band-foot{display:block}.band-legend{margin-bottom:5px}}
  `;

  function injectStyles(){
    if(document.getElementById('valuation-band-style')) return;
    const style=document.createElement('style');style.id='valuation-band-style';style.textContent=css;document.head.appendChild(style);
  }

  const esc=(v)=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
  const fmt=(v,d=2)=>v!=null&&v!==''&&Number.isFinite(Number(v))?Number(v).toLocaleString('ko-KR',{minimumFractionDigits:d,maximumFractionDigits:d}):'-';
  function tickers(){return (typeof perTickers!=='undefined'&&Array.isArray(perTickers))?[...perTickers]:[];}
  function nameOf(t){try{return (typeof perTickerNameMap!=='undefined'&&perTickerNameMap[t])||t;}catch{return t;}}

  function install(){
    injectStyles();
    const metricRow=document.querySelector('.metric-chips');
    const perSection=document.querySelector('#fwdper-tab .per-section');
    if(!metricRow||!perSection||document.querySelector('[data-metric="bands"]')) return;

    const chip=document.createElement('button');
    chip.className='metric-chip';chip.dataset.metric='bands';chip.textContent='📈 역사적 밸류 밴드';
    const pbrChip=metricRow.querySelector('[data-metric="pbr"]');
    if(pbrChip) pbrChip.insertAdjacentElement('afterend',chip); else metricRow.appendChild(chip);

    const section=document.createElement('section');
    section.id='valuation-band-section';section.className='band-section';
    section.innerHTML=`
      <div class="band-head"><div><h2 class="band-title">역사적 밸류에이션 밴드</h2><p class="band-desc">공시 시점을 보수적으로 추정해 재구성한 PER·PBR이 자기 과거 범위에서 어느 위치인지 비교합니다.</p></div></div>
      <div id="band-stock-tabs" class="band-stock-tabs"></div>
      <div class="band-metric-tabs"><button class="band-metric-btn active" data-band-metric="per">TTM PER</button><button class="band-metric-btn" data-band-metric="pbr">PBR</button></div>
      <div id="band-cards" class="band-cards"></div>
      <div class="band-chart-wrap"><div id="band-chart" class="band-chart"></div><div id="band-loading" class="band-loading" style="display:none">밸류 밴드를 계산하는 중...</div></div>
      <div class="band-foot"><div class="band-legend"><span><i class="band-dot" style="background:#3182f6"></i>역사적 값</span><span><i class="band-dot" style="background:#00a86b"></i>20% 구간</span><span><i class="band-dot" style="background:#8b95a1"></i>중앙값</span><span><i class="band-dot" style="background:#f04452"></i>80% 구간</span></div><span id="band-range"></span></div>
      <div id="band-note" class="band-note">과거 재무값을 현재 값처럼 소급 적용하지 않습니다.</div>`;
    perSection.insertAdjacentElement('afterend',section);

    chip.addEventListener('click',(ev)=>{ev.preventDefault();activateBands();});
    metricRow.querySelectorAll('.metric-chip:not([data-metric="bands"])').forEach(btn=>btn.addEventListener('click',()=>deactivateBands()));
    section.querySelectorAll('[data-band-metric]').forEach(btn=>btn.addEventListener('click',()=>{
      section.querySelectorAll('[data-band-metric]').forEach(b=>b.classList.remove('active'));btn.classList.add('active');bandMetric=btn.dataset.bandMetric;render();
    }));

    const tags=document.getElementById('ticker-tags');
    if(tags){let timer=null;new MutationObserver(()=>{clearTimeout(timer);timer=setTimeout(()=>{renderTickerTabs();if(section.style.display!=='none') ensureTickerAndLoad();},100);}).observe(tags,{childList:true,subtree:true});}
  }

  function activateBands(){
    document.querySelectorAll('.metric-chip').forEach(b=>b.classList.toggle('active',b.dataset.metric==='bands'));
    const per=document.querySelector('#fwdper-tab .per-section');if(per) per.style.display='none';
    const section=document.getElementById('valuation-band-section');if(section)section.style.display='block';
    renderTickerTabs();ensureTickerAndLoad();
  }
  function deactivateBands(){
    const per=document.querySelector('#fwdper-tab .per-section');if(per) per.style.display='block';
    const section=document.getElementById('valuation-band-section');if(section)section.style.display='none';
  }

  function renderTickerTabs(){
    const el=document.getElementById('band-stock-tabs');if(!el)return;
    const list=tickers();
    if(!list.length){el.innerHTML='';bandTicker=null;return;}
    if(!bandTicker||!list.includes(bandTicker)) bandTicker=list[0];
    el.innerHTML=list.map(t=>`<button class="band-stock-btn ${t===bandTicker?'active':''}" data-band-ticker="${esc(t)}">${esc(nameOf(t))}</button>`).join('');
    el.querySelectorAll('[data-band-ticker]').forEach(btn=>btn.addEventListener('click',()=>{bandTicker=btn.dataset.bandTicker;renderTickerTabs();load();}));
  }

  function ensureTickerAndLoad(){
    const list=tickers();
    if(!list.length){++requestSeq;if(requestController)requestController.abort();const loading=document.getElementById('band-loading');if(loading)loading.style.display='none';document.getElementById('band-chart').style.visibility='visible';bandTicker=null;bandPayload=null;destroyChart();document.getElementById('band-cards').innerHTML='';document.getElementById('band-chart').innerHTML='<div class="band-empty">상단에서 종목을 먼저 선택해 주세요.</div>';return;}
    if(!bandTicker||!list.includes(bandTicker)) bandTicker=list[0];
    load();
  }

  async function load(){
    if(!bandTicker)return;
    const seq=++requestSeq;if(requestController)requestController.abort();requestController=new AbortController();
    const loading=document.getElementById('band-loading'),chartEl=document.getElementById('band-chart');
    if(loading)loading.style.display='flex';if(chartEl)chartEl.style.visibility='hidden';
    try{
      const r=await fetch(`/api/valuation-band?ticker=${encodeURIComponent(bandTicker)}&years=3`,{cache:'no-store',signal:requestController.signal});
      if(!r.ok){let msg='';try{msg=(await r.json()).error||'';}catch{}throw new Error(msg||`HTTP ${r.status}`);}
      const data=await r.json();if(seq!==requestSeq)return;bandPayload=data;render();
    }catch(e){if(e?.name==='AbortError'||seq!==requestSeq)return;console.error('valuation band error',e);bandPayload=null;destroyChart();if(chartEl){chartEl.style.visibility='visible';chartEl.innerHTML=`<div class="band-empty">${esc(e.message||'역사적 밸류 데이터를 불러오지 못했습니다.')}</div>`;}document.getElementById('band-cards').innerHTML='';}
    finally{if(seq===requestSeq){if(loading)loading.style.display='none';if(chartEl)chartEl.style.visibility='visible';}}
  }

  function destroyChart(){if(resizeObserver){resizeObserver.disconnect();resizeObserver=null;}if(bandChart){try{bandChart.remove();}catch{}bandChart=null;}}

  function render(){
    if(!bandPayload)return;
    const pack=bandPayload[bandMetric];const cards=document.getElementById('band-cards'),range=document.getElementById('band-range'),note=document.getElementById('band-note');
    if(!pack?.stats||!Array.isArray(pack.points)||!pack.points.length){destroyChart();cards.innerHTML='';document.getElementById('band-chart').innerHTML='<div class="band-empty">이 종목은 해당 역사적 지표 데이터가 충분하지 않습니다.</div>';if(range)range.textContent='';return;}
    const s=pack.stats;
    cards.innerHTML=`
      <div class="band-card"><span>마지막 재구성 ${bandMetric.toUpperCase()}</span><strong>${fmt(s.current)}x</strong><small>${esc(s.end)} · ${esc(s.label)}</small></div>
      <div class="band-card"><span>3년 중앙값</span><strong>${fmt(s.median)}x</strong><small>평균 ${fmt(s.mean)}x</small></div>
      <div class="band-card"><span>과거 분포 백분위</span><strong>${fmt(s.percentile,1)}%</strong><small>낮을수록 과거 범위에서 낮은 위치</small></div>
      <div class="band-card"><span>20~80% 밴드</span><strong>${fmt(s.p20)} ~ ${fmt(s.p80)}</strong><small>${s.observations}주 관측치</small></div>`;
    if(range)range.textContent=`${s.start} ~ ${s.end}`;
    if(note){const ex=bandPayload.excluded||{};note.textContent=`공시 시점 근사 재구성 · ${bandPayload.method} · 실제 공시일이 없으면 결산일+${bandPayload.financialLagDays||45}일 가정 · 범위 밖 제외 PER ${ex.perOutOfRange||0}일/PBR ${ex.pbrOutOfRange||0}일 · ${bandPayload.source}. 과거 범위의 위치만 나타내며 본질가치나 매수·매도를 뜻하지 않습니다.`;}
    draw(pack);
  }

  function draw(pack){
    const el=document.getElementById('band-chart');if(!el||!window.LightweightCharts)return;destroyChart();el.innerHTML='';
    bandChart=LightweightCharts.createChart(el,{width:el.clientWidth,height:el.clientHeight||340,localization:{locale:'ko-KR'},layout:{background:{type:LightweightCharts.ColorType.Solid,color:'#ffffff'},textColor:'#6b7684'},grid:{vertLines:{color:'#f2f4f6'},horzLines:{color:'#f2f4f6'}},rightPriceScale:{borderVisible:false},timeScale:{borderVisible:false,timeVisible:false},crosshair:{mode:LightweightCharts.CrosshairMode.Normal}});
    const series=bandChart.addLineSeries({color:'#3182f6',lineWidth:2,priceLineVisible:false,lastValueVisible:true});
    series.setData(pack.points.map(p=>({time:p.time,value:Number(p.value)})));
    const s=pack.stats;
    if(s.p20!=null&&Number.isFinite(Number(s.p20)))series.createPriceLine({price:Number(s.p20),color:'#00a86b',lineWidth:1,lineStyle:LightweightCharts.LineStyle.Dashed,axisLabelVisible:true,title:'20%'});
    if(s.median!=null&&Number.isFinite(Number(s.median)))series.createPriceLine({price:Number(s.median),color:'#8b95a1',lineWidth:1,lineStyle:LightweightCharts.LineStyle.Dotted,axisLabelVisible:true,title:'중앙'});
    if(s.p80!=null&&Number.isFinite(Number(s.p80)))series.createPriceLine({price:Number(s.p80),color:'#f04452',lineWidth:1,lineStyle:LightweightCharts.LineStyle.Dashed,axisLabelVisible:true,title:'80%'});
    bandChart.timeScale().fitContent();
    resizeObserver=new ResizeObserver(()=>{if(bandChart&&el.clientWidth>0)bandChart.applyOptions({width:el.clientWidth,height:el.clientHeight||340});});resizeObserver.observe(el);
  }

  document.addEventListener('DOMContentLoaded',install);
})();
;

/* --- static/js/macro.js --- */
/**
 * 경제 지표 (Macro Insight)
 * - Render에서는 사전 생성된 캐시만 읽음
 * - 금리/스프레드는 변화율보다 bp 변화로 표시
 * - 캐시 생성시각/관측 기준일/출처를 화면에 노출
 * - 탭 재진입 시 이전 차트 인스턴스를 정리해 메모리 누수 방지
 */

let macroCharts = [];
let macroObservers = [];
let macroLoadSeq = 0;

const MACRO_RATE_SYMBOLS = new Set(['T10Y2Y', 'T10Y3M', 'BAMLH0A0HYM2', 'DFII10', 'T10YIE', 'PCEPI', 'PCETRIM12M159SFRBDAL', 'FEDTARGET', 'DFF', 'UNRATE']);

function cleanupMacroCharts() {
    macroObservers.forEach(observer => {
        try { observer.disconnect(); } catch (_) { }
    });
    macroObservers = [];
    macroCharts.forEach(chart => {
        try { chart.remove(); } catch (_) { }
    });
    macroCharts = [];
}

function macroNumber(value, digits = 2) {
    const n = Number(value);
    if (!Number.isFinite(n)) return '-';
    return n.toLocaleString('ko-KR', { maximumFractionDigits: digits });
}

function formatMacroValue(item) {
    const symbol = item.original_symbol || item.symbol;
    const value = Number(item.value);
    if (!Number.isFinite(value)) return 'N/A';

    if (symbol === 'FEDTARGET' && Number.isFinite(Number(item.targetLower)) && Number.isFinite(Number(item.targetUpper))) {
        return `${Number(item.targetLower).toFixed(2)}~${Number(item.targetUpper).toFixed(2)}%`;
    }
    if (MACRO_RATE_SYMBOLS.has(symbol)) return `${macroNumber(value, 2)}%`;
    if (symbol === '^VIX') return macroNumber(value, 2);
    if (symbol === 'RRPONTSYD') return `$${macroNumber(value, 2)}B`;
    if (symbol === 'WALCL' || symbol === 'WTREGEN') return `$${macroNumber(value / 1_000_000, 2)}T`;
    if (symbol === 'M2SL') return `$${macroNumber(value / 1_000, 2)}T`;
    if (symbol === 'RSAFS') return `$${macroNumber(value / 1_000, 1)}B`;
    return macroNumber(value, 2);
}

function formatMacroChange(item) {
    const symbol = item.original_symbol || item.symbol;
    const delta = Number(item.delta);
    const change = Number(item.change);

    if (symbol === 'FEDTARGET' && Number.isFinite(Number(item.moveBp))) {
        const bp = Number(item.moveBp);
        return `${bp > 0 ? '+' : ''}${bp.toFixed(0)}bp 최근 변경`;
    }
    if (MACRO_RATE_SYMBOLS.has(symbol) && Number.isFinite(delta)) {
        const bp = delta * 100;
        return `${bp > 0 ? '+' : ''}${bp.toFixed(Math.abs(bp) < 1 ? 1 : 0)}bp`;
    }
    if (symbol === '^VIX' && Number.isFinite(delta)) {
        return `${delta > 0 ? '+' : ''}${delta.toFixed(2)}pt`;
    }
    if (Number.isFinite(change)) return `${change > 0 ? '+' : ''}${change.toFixed(2)}%`;
    return '-';
}

function formatGeneratedAt(value) {
    if (!value) return '-';
    const d = new Date(value);
    if (Number.isNaN(d.getTime())) return String(value).slice(0, 16);
    return d.toLocaleString('ko-KR', {
        month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false,
    });
}

function bindResponsiveChart(container, chart, height) {
    macroCharts.push(chart);
    if (typeof ResizeObserver === 'undefined') return;
    const observer = new ResizeObserver(entries => {
        const width = Math.floor(entries[0]?.contentRect?.width || 0);
        if (width > 0) chart.resize(width, height);
    });
    observer.observe(container);
    macroObservers.push(observer);
}

async function loadMacroData() {
    const seq = ++macroLoadSeq;
    const grid = document.getElementById('macro-grid');
    if (!grid) return;

    cleanupMacroCharts();
    grid.innerHTML = '<div class="macro-loading-inner"><div class="spinner"></div><p>최신 경제지표 캐시를 불러오는 중...</p></div>';

    const summaryEl = document.getElementById('macro-summary');
    if (summaryEl) summaryEl.remove();
    const freshnessEl = document.getElementById('macro-freshness');
    if (freshnessEl) freshnessEl.remove();

    try {
        const res = await fetch('/api/macro', { cache: 'no-store' });
        if (!res.ok) throw new Error(`macro HTTP ${res.status}`);
        const data = await res.json();
        if (seq !== macroLoadSeq) return;

        if (!Array.isArray(data.results) || data.results.length === 0) {
            grid.innerHTML = '<div class="macro-error">경제지표 캐시가 비어 있습니다.</div>';
            return;
        }

        renderMacroFreshness(data);
        if (data.summary) renderMacroSummary(data.summary);
        if (data.net_liquidity && !data.net_liquidity.error) renderNetLiquidityCard(data.net_liquidity);
        renderMacroGrid(data.results);
    } catch (e) {
        console.error('Macro load error:', e);
        if (seq === macroLoadSeq) grid.innerHTML = '<div class="macro-error">경제지표를 불러오지 못했습니다. 잠시 후 다시 시도해 주세요.</div>';
    }
}

function renderMacroFreshness(data) {
    const section = document.querySelector('.macro-section');
    const header = section?.querySelector('.macro-header');
    if (!section || !header) return;

    const stale = Number(data.staleCount || 0);
    const fresh = Number(data.freshCount || 0);
    const box = document.createElement('div');
    box.id = 'macro-freshness';
    box.className = `macro-freshness ${stale ? 'has-stale' : ''}`;
    box.innerHTML = `
        <span class="macro-fresh-main">${stale ? '일부 지표 직전값 유지' : `${fresh}개 지표 정상 갱신`}</span>
        <span>캐시 ${formatGeneratedAt(data.generatedAt)}</span>
        <span>fresh ${fresh} · stale ${stale}</span>
    `;
    header.insertAdjacentElement('afterend', box);
}

function renderMacroSummary(summary) {
    const text = typeof summary === 'string' ? summary : summary.text;
    const level = typeof summary === 'string' ? 'green' : (summary.level || 'green');
    const basis = typeof summary === 'object' ? summary.latestBasisDate : '';
    const config = {
        red: { label: '위험', className: 'red' },
        yellow: { label: '주의', className: 'yellow' },
        green: { label: '안정', className: 'green' },
    }[level] || { label: '확인', className: 'yellow' };

    const section = document.querySelector('.macro-section');
    const freshness = document.getElementById('macro-freshness');
    if (!section) return;

    const box = document.createElement('div');
    box.id = 'macro-summary';
    box.className = `macro-summary-box macro-summary-${config.className}`;
    box.innerHTML = `
        <div class="traffic-light" aria-hidden="true">
            <span class="tl-dot ${level === 'red' ? 'active' : ''}" style="--dot-color:#F04452"></span>
            <span class="tl-dot ${level === 'yellow' ? 'active' : ''}" style="--dot-color:#FF9800"></span>
            <span class="tl-dot ${level === 'green' ? 'active' : ''}" style="--dot-color:#00C853"></span>
        </div>
        <div class="summary-content">
            <span class="summary-label">시장 환경 · ${config.label}${basis ? ` · 최근 원자료 ${basis}` : ''}</span>
            <span class="summary-text">${text || '요약 데이터가 없습니다.'}</span>
        </div>`;
    if (freshness) freshness.insertAdjacentElement('afterend', box);
    else section.querySelector('.macro-header')?.insertAdjacentElement('afterend', box);
}

function renderNetLiquidityCard(nlData) {
    const grid = document.getElementById('macro-grid');
    if (!grid) return;

    const card = document.createElement('div');
    card.className = 'macro-card net-liquidity-card';
    card.style.gridColumn = '1 / -1';

    const isUp = Number(nlData.change) >= 0;
    const chartId = 'macro-chart-net-liquidity';
    const trillionVal = Number.isFinite(Number(nlData.value)) ? (Number(nlData.value) / 1_000_000).toFixed(2) : '-';
    const asOf = nlData.chart_data?.at(-1)?.time || '-';

    card.innerHTML = `
        <div class="mc-header">
            <span class="mc-name">${nlData.name} <span class="nl-badge">CORE</span></span>
            <span class="mc-symbol">WALCL - TGA - RRP</span>
        </div>
        <div class="mc-value-row">
            <span class="mc-value">$${trillionVal}T</span>
            <span class="mc-change ${isUp ? 'up' : 'down'}">${Number(nlData.change) > 0 ? '+' : ''}${macroNumber(nlData.change, 2)}%</span>
        </div>
        <div class="mc-chart-wrapper">
            <div id="${chartId}" class="mc-mini-chart mc-mini-chart-core"></div>
            <div class="mc-chart-dates"><span>${nlData.chart_data?.[0]?.time || ''}</span><span>${asOf}</span></div>
        </div>
        <div class="mc-desc">${nlData.desc}</div>
        <div class="mc-meta">기준 ${asOf} · Fed 총자산 - TGA - RRP</div>`;

    grid.appendChild(card);
    requestAnimationFrame(() => drawMacroArea(chartId, nlData.chart_data || [], isUp, 120));
}

function sparklineSvg(rows, isUp, height = 80, area = false) {
    const clean = (rows || []).map((row, index) => ({
        x: index,
        value: Number(row?.value),
    })).filter((row) => Number.isFinite(row.value));
    if (clean.length < 2) return '';

    const values = clean.map((row) => row.value);
    let min = Math.min(...values);
    let max = Math.max(...values);
    if (max === min) { max += 0.5; min -= 0.5; }
    const pad = (max - min) * 0.08;
    max += pad; min -= pad;

    const width = 100;
    const yTop = 5;
    const yBottom = height - 6;
    const points = clean.map((row, index) => {
        const x = clean.length === 1 ? width / 2 : (index / (clean.length - 1)) * width;
        const y = yBottom - ((row.value - min) / (max - min)) * (yBottom - yTop);
        return [x, y];
    });
    const line = points.map(([x, y], index) => `${index ? 'L' : 'M'}${x.toFixed(2)},${y.toFixed(2)}`).join(' ');
    const stroke = isUp ? '#F04452' : '#3182F6';
    const fill = area ? `${line} L100,${height} L0,${height} Z` : '';
    return `<svg class="macro-sparkline" viewBox="0 0 100 ${height}" width="100%" height="100%" preserveAspectRatio="none" overflow="hidden" aria-hidden="true">
        ${area ? `<path d="${fill}" fill="${stroke}" fill-opacity=".10"></path>` : ''}
        <path d="${line}" fill="none" stroke="${stroke}" stroke-width="2" vector-effect="non-scaling-stroke" stroke-linecap="round" stroke-linejoin="round"></path>
    </svg>`;
}

function drawMacroArea(chartId, rows, isUp, height) {
    const container = document.getElementById(chartId);
    if (!container || !rows.length) return;
    container.innerHTML = sparklineSvg(rows, isUp, height, true);
}

function renderMacroGrid(indicators) {
    const grid = document.getElementById('macro-grid');
    if (!grid) return;
    const loading = grid.querySelector('.macro-loading-inner');
    if (loading) loading.remove();

    indicators.forEach((item, index) => {
        const symbol = item.original_symbol || item.symbol;
        const hasChart = Array.isArray(item.chart_data) && item.chart_data.length > 0;
        const isUp = Number(item.delta ?? item.change) >= 0;
        const chartId = `macro-chart-${index}`;
        const card = document.createElement('div');
        card.className = `macro-card ${item.stale ? 'macro-card-stale' : ''}`;
        card.tabIndex = item.link ? 0 : -1;
        card.setAttribute('role', item.link ? 'link' : 'group');
        card.setAttribute('aria-label', `${item.name}, 기준 ${item.asOf || '-'}`);

        const open = () => { if (item.link) window.open(item.link, '_blank', 'noopener'); };
        card.addEventListener('click', open);
        card.addEventListener('keydown', e => {
            if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); open(); }
        });

        card.innerHTML = `
            <div class="mc-header">
                <span class="mc-name">${item.name}${item.stale ? ' <span class="stale-badge">STALE</span>' : ''} <span class="link-icon">↗</span></span>
                <span class="mc-symbol">${symbol}</span>
            </div>
            <div class="mc-value-row">
                <span class="mc-value">${formatMacroValue(item)}</span>
                <span class="mc-change ${isUp ? 'up' : 'down'}">${formatMacroChange(item)}</span>
            </div>
            <div class="mc-chart-wrapper">
                <div id="${chartId}" class="mc-mini-chart">${hasChart ? '' : '<div class="no-chart">시계열 없음</div>'}</div>
                ${hasChart ? `<div class="mc-chart-dates"><span>${item.chart_data[0]?.time || ''}</span><span>${item.asOf || item.chart_data.at(-1)?.time || ''}</span></div>` : ''}
            </div>
            <div class="mc-desc">${item.desc}</div>
            <div class="mc-meta">기준 ${item.asOf || '-'} · ${item.source || '공개 경제데이터'}</div>`;

        grid.appendChild(card);
        if (hasChart) requestAnimationFrame(() => drawMacroLine(chartId, item.chart_data, isUp, symbol));
    });
}

function drawMacroLine(chartId, rows, isUp) {
    const container = document.getElementById(chartId);
    if (!container || !rows?.length) return;
    container.innerHTML = sparklineSvg(rows, isUp, 80, false);
}
;

